"""Cuaderno del estudiante, 5.º básico Lenguaje y Comunicación: OA 25 (apreciación de teatro y lenguaje audiovisual) y OA 26 (diálogo para desarrollar ideas y acuerdos).

Todas las escenas y diálogos son originales y breves; cada ejercicio trae el texto que necesita.
No se requiere ver ninguna obra ni película: las escenas vienen escritas. Ver una obra o película real queda para el docente o la familia.
Nota: los títulos de las clases del currículo son genéricos; este cuaderno sigue el OA oficial.
"""
from __future__ import annotations

from student_lessons import ex, register

OA25, OA26 = "LE05 OA 25", "LE05 OA 26"
E = ex


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, materials, use, prior, explain, vocab, worked, mistakes, tiers, ctx, sc, open_task, reinforce, extend):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=ctx, selfcheck=sc, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


ESC = ("Escena en la plaza. Personajes: MARTA y DIEGO. "
       "MARTA (con voz firme): La pelota rodó hacia el árbol. Yo iré por ella. "
       "DIEGO (nervioso, mirando al suelo): Mejor espera... ¿y si hay un perro grande? "
       "MARTA (sonriendo): Los perros grandes también pueden ser amistosos. Vamos juntos. "
       "(Diego respira hondo y la sigue.)")
OBRA = ("Obra «El faro apagado». Escena 1: en un pueblo costero, el faro dejó de funcionar y los pescadores no pueden volver de noche. "
        "Escena 2: la niña Rita sube al faro con el farero y descubre que una tormenta rompió el cable de la luz. "
        "Escena 3: Rita avisa a los vecinos y, entre todos, con ayuda de un electricista, arreglan el cable y el faro vuelve a brillar.")
VOCES = ("ABUELA TERESA: Mi niña, ven a sentarte, que hay sopa calentita y pan tibio. "
         "CAPITÁN BRAVO: ¡Silencio en cubierta! ¡Nadie se mueve hasta que yo lo ordene! "
         "TOMÁS: Eh... bueno... yo creo que... no sé si es buena idea...")
CAMILO = ("Escena en la escuela. A Nico se le cae la bandeja y todos ríen. Camilo no ríe: recoge la bandeja y le dice en voz baja: "
          "«Tranquilo, a todos nos pasa». Nico, sorprendido, sonríe.")

