  [E("En una obra, un personaje dice: «¡Largo de aquí! ¡No quiero verte!». ¿Qué emoción muestra: enojo o alegría?", "Enojo", "Las exclamaciones y el rechazo lo muestran.")],
  [E("¿Cómo muestran los personajes cómo son?", "Con su manera de hablar y de actuar", "No siempre lo dicen directamente."),
   E("En Lenguaje: ¿Qué es la evidencia al describir un personaje?", "Una frase que apoya mi descripción", "La cito de la obra."),
   E("¿Qué muestran los puntos suspensivos?", "Duda o pausa", "Dejan la frase sin terminar.")],
