HUERTO = ("Tomás: Creo que sí debemos hacer un huerto, porque así comeremos verduras frescas y aprenderemos a cuidar las plantas. "
          "Pía: Yo creo que no, porque no hay una llave de agua cerca del patio. "
          "Lola: A mí no me gusta la tierra.")

L(OA26, 3,
  "Este cuaderno y lápiz. Los diálogos vienen escritos en los ejercicios.",
  "Aprenderé a fundamentar mi postura con razones y a reconocer razones fuertes. Sirve para que mis ideas convenzan con respeto y no solo con gustos.",
  ["Sé mantener el foco en un tema.", "Sé distinguir opinión de razón."],
  ["Una postura es lo que piensas sobre un tema: «Creo que sí debemos hacer un huerto». Fundamentarla es dar razones que la apoyen: «porque así comeremos verduras frescas». Una razón responde a ¿por qué piensas eso? Sin razones, la postura es solo un gusto personal y es difícil que otros la entiendan.",
   "Hay razones más fuertes que otras. Una razón fuerte tiene relación con el tema y se puede comprobar o entender: «no hay una llave de agua cerca del patio» es un hecho que afecta al huerto. «No me gusta la tierra» es una preferencia personal; sirve para explicar tu sentir, pero no basta para decidir por todos.",
   "Para fundamentar, usa frases como «Pienso que... porque...», «Una razón es que...». Y escucha las razones de los demás: puedes cambiar de postura si te convencen. Fundamentar no es ganar; es ayudar al grupo a decidir con buenas razones."],
  [("postura", "lo que pienso sobre un tema"), ("fundamentar", "apoyar con razones"), ("razón", "motivo que explica una postura"), ("preferencia", "lo que me gusta o no me gusta"), ("hecho", "algo que se puede comprobar"), ("convencer", "lograr que alguien comparta mi idea")],
  [("Postura y razón", f"{HUERTO} ¿Cuál es la postura de Pía y cuál es su razón?", ["Postura: no.", "Razón: no hay llave de agua cerca.", "La razón está tras «porque»."], "Postura: no al huerto. Razón: no hay llave de agua cerca."),
   ("Razón fuerte", "¿Cuál es una razón más fuerte: «no hay una llave de agua cerca» o «no me gusta la tierra»?", ["La primera es un hecho.", "La segunda es una preferencia.", "La primera es más fuerte."], "«No hay una llave de agua cerca».")],
  [("Dar una postura sin razón.", "No se entiende por qué.", "Agrega «porque...»."),
   ("Usar solo gustos personales como razón.", "No sirve para decidir por el grupo.", "Busca razones que se puedan comprobar.")],
  ([E(f"{HUERTO} ¿Cuál es la postura de Tomás?", "Hacer un huerto", "Lo dice al comienzo."),
    E(f"{HUERTO} ¿Quién dice que no hay una llave de agua cerca del patio?", "Pía", "Lo dice tras «porque»."),
    E("¿Qué palabra introduce una razón: porque o también?", "Porque", "Indica el motivo.")],
   [E(f"{HUERTO} ¿Qué razón da Tomás?", "Comerán verduras frescas y aprenderán a cuidar las plantas", "Son los beneficios que menciona."),
    E(f"{HUERTO} ¿La opinión de Lola está fundamentada?", "No", "Solo dice que no le gusta la tierra."),
    E("Una razón fuerte, ¿se relaciona con el tema o con el gusto personal de quien habla?", "Con el tema", "Debe ayudar a decidir por el grupo.")],
   [E("Tema: ¿Podemos prestar libros a otros cursos? ¿Qué razón es más fuerte? A: «Así más estudiantes leerán». B: «Me aburre la biblioteca».", "A", "Es un beneficio que se puede entender."),
    E("Completa con una razón: «Creo que debemos reciclar papel porque ___». ¿Cuál continuación es más fuerte? A: «se puede usar otra vez» B: «el color me gusta».", "A", "Es una razón relacionada con el tema."),
    E("Tema: ¿Hacer el paseo en invierno? Elige la razón fuerte: «Hace mucho frío y llueve en esa época» o «Odio los paseos».", "Hace mucho frío y llueve en esa época", "Es un hecho relacionado con el paseo.")],
   [E("Ema dice «No quiero un huerto». Luis dice «No quiero un huerto porque no hay agua cerca». ¿Quién fundamentó mejor?", "Luis", "Da una razón."),
    E("¿Puedes cambiar de postura si te convencen con buenas razones?", "Sí", "Dialogar es considerar las razones de otros.")],
   [E("Pedro dice: «Hay que tener huerto porque lo digo yo». ¿Es una razón?", "No", "No explica nada sobre el tema."),
    E("Escribe una razón para «Creo que debemos tener recreos largos» basada en un beneficio (no en un gusto).", "Porque así podemos descansar y jugar más", "Es un beneficio razonable.")]),
  [E("Tu curso decide si tener una mascota en la sala. ¿Qué razón es más fuerte para decir que no: «Algunos estudiantes son alérgicos» o «No me gustan los animales»?", "Algunos estudiantes son alérgicos", "Es un hecho que afecta al grupo.")],
  [E("En Lenguaje: ¿Qué es una postura?", "Lo que pienso sobre un tema", "Puede ser a favor o en contra."),
   E("En Lenguaje: ¿Qué es fundamentar?", "Apoyar mi postura con razones", "Responde al por qué."),
   E("¿Qué razón es más fuerte: un hecho comprobable o un gusto personal?", "Un hecho comprobable", "Sirve para decidir por todos.")],
  (f"Lee el diálogo: «{HUERTO}». Escribe la postura de cada uno, su razón y cuál te parece más fuerte, con una justificación. Luego escribe tu postura sobre «tener un huerto en el patio» con dos razones.",
   "Tomás: a favor, verduras frescas. Pía: en contra, no hay agua cerca. Lola: solo da una preferencia («no me gusta la tierra»), no una razón sólida. La de Pía es fuerte porque es un hecho. Mi postura: a favor, porque aprenderemos a cuidar plantas y porque habrá verduras para compartir.",
   ["identifica posturas y razones", "evalúa la fuerza", "escribe su postura con dos razones"], ["tabla breve y postura propia"], ["razones que son gustos", "sin justificar"],
   "Comprueba que cada razón responda a «¿por qué?» y se relacione con el tema."),
  "Elige un tema de tu casa (como los horarios) y escribe tu postura con una razón.",
  "Escribe dos razones fuertes y una débil sobre «usar uniforme en la escuela».")

# ================================================================ OA 26 · clase 4
L(OA26, 4,
  "Este cuaderno y lápiz. Los diálogos vienen escritos en los ejercicios.",
  "Aprenderé a mostrar acuerdo o desacuerdo con respeto y a comparar formas de responder. Sirve para que podamos pensar distinto sin ofendernos.",
  ["Sé fundamentar una postura.", "Sé aceptar sugerencias."],
  ["En un diálogo es normal que haya acuerdo o desacuerdo. Para mostrar acuerdo puedes decir: «Estoy de acuerdo contigo porque...», «Coincido con Ema en que...». Para mostrar desacuerdo con respeto puedes decir: «No comparto tu idea porque...», «Entiendo lo que dices, pero pienso que...». Siempre das una razón.",
   "El respeto se nota en lo que decimos y cómo lo decimos. Criticar la idea es distinto de ofender a la persona. «Esa idea no resuelve el problema del agua» critica la idea. «Eres tonto» ofende a la persona. Un desacuerdo respetuoso permite seguir conversando y llegar a un acuerdo.",
   "A veces conviene reformular lo que dijo la otra persona antes de discrepar: «Si entendí bien, propones... pero pienso que...». También puedes buscar un punto en común: «Coincidimos en que queremos un huerto; no coincidimos en dónde ponerlo». Así el desacuerdo se vuelve un paso para acordar."],
  [("acuerdo", "coincidir con la idea de otro"), ("desacuerdo", "pensar distinto a otro"), ("respeto", "trato amable que valora a la otra persona"), ("reformular", "decir con otras palabras lo que dijo otro"), ("punto en común", "idea en que todos coinciden"), ("discrepar", "mostrar que pienso distinto")],
  [("Desacuerdo respetuoso", "Compara. A: «No comparto tu idea porque no hay agua cerca». B: «Eres tonto, no sabes nada». ¿Cuál muestra desacuerdo con respeto?", ["A da una razón y critica la idea.", "B ofende a la persona.", "A es respetuosa."], "A."),
   ("Punto en común", "Ema quiere el huerto junto a la sala y Luis lo quiere junto al patio. ¿Qué punto en común tienen?", ["Ambos quieren un huerto.", "Discrepan en el lugar.", "Su punto en común es el huerto."], "Que ambos quieren hacer un huerto.")],
  [("Responder «Eso es tonto».", "Ofende a la persona y no da razón.", "Critica la idea con una razón."),
   ("Mostrar desacuerdo sin escuchar.", "No se entiende la idea del otro.", "Reformula antes de discrepar.")],
  ([E("«Estoy de acuerdo contigo porque así cuidamos el patio.» ¿Muestra acuerdo o desacuerdo?", "Acuerdo", "Dice estar de acuerdo y da razón."),
    E("«No comparto tu idea porque no hay agua cerca.» ¿Muestra acuerdo o desacuerdo?", "Desacuerdo", "Dice no compartir la idea."),
    E("¿Qué debe llevar siempre un desacuerdo respetuoso?", "Una razón", "Explica por qué pienso distinto.")],
   [E("¿Cuál critica la idea y no a la persona: «Esa idea no resuelve el problema del agua» o «Eres tonto»?", "Esa idea no resuelve el problema del agua", "La segunda ofende."),
    E("En Lenguaje: ¿Qué es reformular?", "Decir con otras palabras lo que dijo el otro", "Verifica que entendí."),
    E("¿Puedo estar en desacuerdo y seguir siendo respetuoso?", "Sí", "Si critico la idea con razones y buen trato.")],
   [E("Un compañero propone cambiar la hora del recreo. No estás de acuerdo. ¿Qué respuesta es respetuosa? A: «Entiendo tu idea, pero pienso que los más chicos necesitan más tiempo para jugar». B: «Qué mala idea».", "A", "A da una razón y no ofende."),
    E("Ema dice que le gusta tu idea de decorar la sala. ¿Qué respuesta muestra acuerdo y aporta? A: «Coincido, y podríamos agregar flores de papel». B: «Sí».", "A", "A coincide y agrega algo."),
    E("Un compañero y tú proponen lugares distintos para el paseo. Ambos quieren hacer un paseo. ¿Cuál es el punto en común?", "Que ambos quieren hacer un paseo", "Es en lo que coinciden.")],
   [E("Dos compañeros discrepan: uno dice «Eso no sirve» y otro «Entiendo tu idea, pero pienso que falta agua». ¿Cuál mantiene mejor el diálogo?", "El segundo", "Da razones y respeta."),
    E("Si reformulas la idea del otro antes de discrepar, ¿cómo cambia la conversación?", "Se entiende mejor y hay más respeto", "Demuestra que escuchaste.")],
   [E("Tomás dice que lo mejor es el huerto junto a la sala. Elige la forma respetuosa de pensar distinto: A «Entiendo tu idea, pero pienso que junto al patio recibiría más sol» B «Qué idea más mala».", "A", "Reconoce la idea y da una razón."),
    E("Alguien discrepa de ti diciéndote «No sirves para esto». ¿Qué conviene responder: «Prefiero que critiques mi idea con razones» o «Tú tampoco»?", "Prefiero que critiques mi idea con razones", "Pide respeto sin ofender.")]),
  [E("En una reunión, alguien propone vender galletas para el paseo y tú prefieres una rifa. ¿Qué dices: «Entiendo tu idea, pero prefiero la rifa porque se junta más dinero» o «Tu idea es mala»?", "Entiendo tu idea, pero prefiero la rifa porque se junta más dinero", "Da una razón y respeta.")],
  [E("¿Qué muestra «No comparto tu idea porque...»?", "Un desacuerdo con razón", "Explica por qué pienso distinto."),
   E("En Lenguaje: ¿Qué es un punto en común?", "Una idea en que todos coinciden", "Ayuda a buscar acuerdos."),
   E("¿Se puede discrepar sin ofender?", "Sí", "Criticando la idea y no a la persona.")],
  ("Lee con otra persona estas frases y clasifícalas como acuerdo respetuoso, desacuerdo respetuoso o ataque: 1) «Coincido contigo porque ayudaría a todos». 2) «Eso es de tontos». 3) «Entiendo tu idea, pero pienso que no alcanza el tiempo». Luego conversen sobre «hacer un álbum del curso». Cada uno propone una idea, una muestra acuerdo y otra desacuerdo respetuoso. Anota una frase que usaste.",
   "1) Acuerdo respetuoso. 2) Ataque. 3) Desacuerdo respetuoso. En mi diálogo: «Entiendo tu idea, pero pienso que mejor sería hacerlo en grupos porque así se termina antes».",
   ["clasifica las tres frases", "usa una frase de acuerdo y una de desacuerdo respetuoso", "da razones"], ["clasificación y frase usada"], ["responder con ataques", "discrepar sin razón"],
   "Revisa que tu desacuerdo critique la idea y no a la persona."),
  "Escribe dos frases respetuosas para mostrar desacuerdo.",
  "Cambia tres frases de ataque por frases de desacuerdo respetuoso.")

# ================================================================ OA 26 · clase 5
L(OA26, 5,
  "Este cuaderno y lápiz. Para el diálogo final necesitas una o dos personas de tu casa; si estás solo, escribe un diálogo imaginario.",
  "Aprenderé a dialogar para llegar a un acuerdo aplicando todo lo aprendido: foco, turnos, sugerencias, razones y respeto. Sirve para decidir con otros de forma justa.",
  ["Sé mantener el foco, respetar turnos y aceptar sugerencias.", "Sé fundamentar y discrepar con respeto."],
  ["Un diálogo para llegar a un acuerdo tiene pasos. Primero, se dice el tema y el propósito: «Vamos a decidir qué haremos en el cierre del año». Segundo, cada persona propone una idea con una razón. Tercero, se comentan las ideas, se hacen sugerencias y se muestra acuerdo o desacuerdo con respeto. Cuarto, se elige una opción o se combinan ideas. Quinto, se repite el acuerdo para confirmar.",
   "Durante el diálogo, mantén el foco, espera tu turno, escucha con atención y usa frases como «Estoy de acuerdo porque...», «Entiendo tu idea, pero...», «¿Y si combinamos...?». Cuando haya dos ideas fuertes, buscar un punto en común o combinarlas ayuda a que todos sientan que su opinión importó.",
   "Al terminar, revisa: ¿sabíamos el tema?, ¿todos hablaron?, ¿dimos razones?, ¿nos respetamos?, ¿llegamos a un acuerdo claro? Si algo falló, piensa qué harías distinto. Este cuaderno no puede grabar tu diálogo, por eso la evidencia es tu registro escrito."],
  [("acuerdo", "decisión aceptada por todos"), ("combinar", "unir partes de varias ideas"), ("confirmar", "repetir lo acordado para asegurarse"), ("registro", "anotación de lo conversado"), ("propósito", "lo que queremos lograr"), ("opción", "alternativa entre las que se elige")],
  [("Combinar ideas", "Ema propone un cuento en el acto y Luis un baile. ¿Qué acuerdo combina las ideas?", ["Hay dos ideas válidas.", "Se pueden unir.", "Un baile que cuente un cuento."], "Hacer un baile que cuente un cuento."),
   ("Confirmar el acuerdo", "Después de decidir, ¿qué conviene hacer?", ["Repetir lo acordado.", "Asegurar que todos entendieron.", "Confirmar."], "Repetir el acuerdo para confirmarlo.")],
  [("Imponer mi idea sin escuchar a otros.", "No hay acuerdo, hay imposición.", "Escucha y busca un punto en común."),
   ("Terminar sin confirmar lo acordado.", "Puede haber malentendidos.", "Repite el acuerdo.")],
  ([E("¿Qué se dice primero al comenzar un diálogo para llegar a un acuerdo: el tema y el propósito o la idea que más te gusta?", "El tema y el propósito", "Así todos saben qué se decide."),
    E("¿Qué debe acompañar cada idea que propones?", "Una razón", "Explica por qué la propones."),
    E("¿Qué se hace al final: confirmar lo acordado o irse sin decir nada?", "Confirmar lo acordado", "Así se evitan malentendidos al final.")],
   [E("Rosa propone una feria de libros y Tomás una feria de juegos. ¿Qué acuerdo combina ambas ideas: una feria con un rincón de libros y otro de juegos o cancelar la feria?", "Una feria con un rincón de libros y otro de juegos", "Une partes de las dos propuestas."),
    E("¿Qué frase propone combinar ideas: «¿Y si combinamos tu cuento y mi baile?» o «Mi idea es mejor»?", "¿Y si combinamos tu cuento y mi baile?", "Busca un acuerdo."),
    E("¿Para qué sirve tener un registro escrito del diálogo?", "Para dejar evidencia de lo conversado y acordado", "Permite revisarlo después con calma.")],
   [E("Tres ideas: a) un cuento, b) un baile, c) cantar. El grupo vota y salen 2 votos para el baile, 1 para el cuento y 0 para cantar. ¿Qué opción tiene más votos?", "El baile", "Tiene 2 votos."),
    E("Los dos votos son para el baile y uno para el cuento. Para que el grupo se sienta escuchado, ¿qué puede hacer: sumar un cuento al baile o ignorar el cuento?", "Sumar un cuento al baile", "Incluye la idea minoritaria."),
    E("Si dos personas discrepan, ¿qué es conveniente: buscar un punto en común o seguir insistiendo?", "Buscar un punto en común", "Permite avanzar hacia un acuerdo.")],
   [E("Después del diálogo, un integrante dice: «Entonces quedamos en un baile que cuente un cuento, el viernes». ¿Qué hizo?", "Confirmó el acuerdo", "Repitió lo decidido."),
    E("Ema siempre habla y Rosa nunca. ¿Qué podría hacer el grupo para mejorar? A: «Dar un turno a Rosa». B: «Hacer callar a Ema».", "A", "Garantiza que todos participen.")],
   [E("Un grupo no llegó a acuerdo. ¿Qué puede hacer en la próxima reunión: repasar las razones y buscar un punto en común o decidir por el que grita más?", "Repasar las razones y buscar un punto en común", "Permite un acuerdo justo."),
    E("¿Qué frase propone una votación respetuosa? A «¿Votamos para decidir?» B «Se hace lo que yo digo».", "A", "Invita a decidir entre todos.")]),
  [E("Tu familia debe elegir cómo celebrar un cumpleaños. ¿Qué haces primero: decir el tema y proponer ideas con razones o imponer tu idea?", "Decir el tema y proponer ideas con razones", "Así se busca un acuerdo.")],
  [E("¿Qué pasos tiene un diálogo para llegar a un acuerdo?", "Tema, ideas con razones, comentarios y acuerdo", "Se confirma al final."),
   E("En Lenguaje: ¿Qué es combinar ideas?", "Unir partes de varias propuestas", "Ayuda a que todos se sientan escuchados."),
   E("¿Por qué confirmar el acuerdo?", "Para evitar malentendidos", "Todos repiten lo decidido.")],
  ("Conversa con una o dos personas de tu casa para decidir «qué actividad haremos juntos el fin de semana»: A) una caminata cerca de casa, B) una tarde de juegos de mesa, C) preparar una comida entre todos. Antes de empezar, escribe el tema. Durante el diálogo, cada persona da una idea con una razón y alguien muestra desacuerdo con respeto. Al final confirmen el acuerdo. Escribe un registro de cuatro líneas: tema, razones, una sugerencia aceptada y el acuerdo.",
   "Tema: actividad del fin de semana. Razones: la caminata es gratis y hace bien; los juegos son para todos. Sugerencia aceptada: hacer juegos si llueve. Acuerdo: caminata el sábado y juegos de mesa el domingo.",
   ["escribe el tema", "da una razón por idea", "muestra desacuerdo con respeto", "confirma el acuerdo"], ["registro de cuatro líneas"], ["imponer una idea", "no confirmar"],
   "Pregunta al final: ¿nos escuchamos todos y quedó claro el acuerdo?"),
  "Escribe tres frases para proponer un acuerdo.",
  "Escribe un diálogo de ocho líneas en que tres amigos acuerdan una actividad.")
